SELECT r.x AS x, t.v1 AS v1, t.v2 AS v2 FROM (SELECT * FROM (SELECT InvoiceLineId AS x, InvoiceLineId AS v1 FROM InvoiceLine) AS r WHERE EXISTS (SELECT 1 FROM (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT InvoiceLineId AS x, InvoiceId AS v1 FROM InvoiceLine) AS r JOIN (SELECT * FROM (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT InvoiceId AS x, CustomerId AS v1 FROM Invoice) AS r JOIN (SELECT CustomerId AS x, Country AS v1 FROM Customer) AS t ON r.v1 = t.x LIMIT -1) AS r WHERE r.v1 = 'Brazil') AS t ON r.v1 = t.x LIMIT -1) AS t WHERE t.x = r.v1) LIMIT -1) AS r JOIN (SELECT r.x AS x, t.v1 AS v1, t.v2 AS v2 FROM (SELECT InvoiceLineId AS x, TrackId AS v1 FROM InvoiceLine) AS r JOIN (SELECT Track.TrackId AS x, Track.Name AS v1, t2.v1 AS v2 FROM Track JOIN (SELECT r.x AS x, t.v1 AS v1 FROM (SELECT AlbumId AS x, ArtistId AS v1 FROM Album) AS r JOIN (SELECT ArtistId AS x, Name AS v1 FROM Artist) AS t ON r.v1 = t.x LIMIT -1) AS t2 ON Track.AlbumId = t2.x LIMIT -1) AS t ON r.v1 = t.x LIMIT -1) AS t ON r.v1 = t.x;
